/**
 * Converts a list of changes to an object:
 * {
 *   "changes.0.one": "value one",
 *   "changes.0.two": "value two"
 * }
 * Becomes:
 * {
 *   changes: {
 *   [
 *    {
 *     one: "value one",
 *     two: "value two",
 *    }
 *   ]
 * }
 */
export function changesToData(changes) {
    const data = {};
    for (const [key, value] of Object.entries(changes)) {
        const parts = key.split(".");
        // deno-lint-ignore no-explicit-any
        let item = data;
        while (true) {
            let part = parts.shift();
            // if it's a numeric string prepend 0 to avoid automatic sorting
            if (part === "0" || part.match(/^[1-9]\d*$/)) {
                part = `0${part}`;
            }
            if (!parts.length) {
                item[part] = value;
                break;
            }
            if (part in item) {
                item = item[part];
                continue;
            }
            item[part] = {};
            item = item[part];
        }
    }
    return data;
}
export async function prepareField(field, content, data, document) {
    const json = { ...field };
    if ("fields" in json) {
        json.fields = await Promise.all(json.fields.map((f) => prepareField(f, content, data?.[field.name], document)));
    }
    if (json.init) {
        // deno-lint-ignore no-explicit-any
        await json.init(json, content, data, document);
    }
    return json;
}
export function getViews(field, views = new Set()) {
    if (typeof field.view === "string") {
        views.add(field.view);
    }
    if ("fields" in field) {
        field.fields.forEach((f) => getViews(f, views));
    }
    return views;
}
